using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using McpServer.Tools;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer()
    .WithStdioTransport()
    .WithToolsFromAssembly();

// Register a named HttpClient for the weather API
builder.Services.AddHttpClient("WeatherApi", client =>
{
    client.BaseAddress = new Uri("https://api.open-meteo.com/");
    client.DefaultRequestHeaders.Add("User-Agent", "McpServer/1.0");
});

await builder.Build().RunAsync();

using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

/// <summary>
/// MCP tools that wrap the Open-Meteo weather REST API.
/// The MCP SDK instantiates this class per-call via DI,
/// so constructor-injected services are fully supported.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    // Constructor injection — the DI container resolves IHttpClientFactory automatically
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool(Name = "get_weather")]
    [McpServerToolDescription("Gets current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeatherAsync(
        [McpServerToolParameter(Description = "Latitude of the location")] double latitude,
        [McpServerToolParameter(Description = "Longitude of the location")] double longitude)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var current = json.GetProperty("current");

        var temp = current.GetProperty("temperature_2m").GetDouble();
        var wind = current.GetProperty("wind_speed_10m").GetDouble();

        return $"Temperature: {temp}°C, Wind: {wind} km/h";
    }

    [McpServerTool(Name = "get_forecast")]
    [McpServerToolDescription("Gets a 7-day daily forecast for a location.")]
    public async Task<string> GetForecastAsync(
        [McpServerToolParameter(Description = "Latitude of the location")] double latitude,
        [McpServerToolParameter(Description = "Longitude of the location")] double longitude)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&daily=temperature_2m_max,temperature_2m_min&timezone=auto";

        var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        return json.GetProperty("daily").ToString();
    }
}

